/**
 * Write to stdout and wait for the flush. Help and JSON can be larger than a
 * pipe buffer, and `process.exit` after `main()` would cut them short.
 */
export function writeStdout(text) {
    return new Promise((resolve, reject) => {
        process.stdout.write(text, (error) => {
            if (error) {
                reject(error);
                return;
            }
            resolve();
        });
    });
}
/**
 * Ask on stderr and read one line from stdin. Resolves undefined when stdin
 * or stderr is not a TTY: then no person is there to answer.
 */
export async function askOnTty(question) {
    // isTTY is undefined, not false, on a stream that is not a TTY.
    if (!process.stdin.isTTY || !process.stderr.isTTY) {
        return undefined;
    }
    const { createInterface } = await import("node:readline/promises");
    const prompt = createInterface({ input: process.stdin, output: process.stderr });
    try {
        return await prompt.question(question);
    }
    finally {
        prompt.close();
    }
}
